import { copyToClipboard, getAirbusIcons, getIconID } from "../../doc/docutils";
import IconDoc from "./Icons.doc.mdx";

const meta = {
  id: "General/Visual Styles/Icons",
  title: "General/Visual Styles/Icons",
  parameters: {
    docs: {
      page: IconDoc,
    },
  },
};
export default meta;

export const Airbus = {
  render: () => (
    <div class="ds-text--body p-1">
      <div class="ds-text--label ds-text--small">
        Mouse over icons to see names. Click to copy to the clipboard.
      </div>
      <br />
      <div class="icons-list">
        {getAirbusIcons().map(function (iconKey) {
          const iconId = getIconID(iconKey);

          return (
            <button
              key={iconKey}
              class="iconitem"
              onClick={() => copyToClipboard(iconId)}
            >
              <i class={`ds-icon ds-icon--large ds-icon-${iconId}`}></i>
              <span class="ds-text--small iconitem-name">{iconId}</span>
            </button>
          );
        })}
      </div>
    </div>
  ),

  name: "airbus",
};

export const Material = {
  render: () => (
    <div class="icons-list">
      <i class="mat-icon ds-icon--large">home</i>
      <i class="mat-icon ds-icon--large">settings</i>
      <i class="mat-icon ds-icon--large">delete</i>
      <i class="mat-icon ds-icon--large">room</i>
      <i class="mat-icon ds-icon--large">feedback</i>
    </div>
  ),

  name: "material",
};
